function renderStats(){const e=document.getElementById("stats-grid");e&&"undefined"!=typeof JAHANGIR_INFO&&(e.innerHTML=JAHANGIR_INFO.quickStats.map(e=>`\n        <div class="stat-card">\n            <span class="stat-icon">${e.icon}</span>\n            <div class="stat-val">${e.value}</div>\n            <div class="stat-lbl">${e.label}</div>\n        </div>\n    `).join(""))}function renderZodiacSelector(){const e=document.getElementById("zodiac-selector-grid");e&&"undefined"!=typeof ZODIAC_SIGNS&&(e.innerHTML=ZODIAC_SIGNS.map(e=>`\n        <button class="zodiac-btn" id="btn-zodiac-${e.id}" onclick="selectZodiacSign('${e.id}')">\n            <span class="zodiac-icon">${e.symbol.split(" ")[0]}</span>\n            <span class="zodiac-title">${e.name.split(" ")[0]}</span>\n        </button>\n    `).join(""))}function renderTimeline(){const e=document.getElementById("timeline-container");e&&"undefined"!=typeof TIMELINE_EVENTS&&(e.innerHTML=TIMELINE_EVENTS.map(e=>`\n        <div class="timeline-card">\n            <div class="timeline-year">${e.year}</div>\n            <div class="timeline-content">\n                <h3>${e.title}</h3>\n                <p>${e.description}</p>\n            </div>\n        </div>\n    `).join(""))}function renderReferences(){const e=document.getElementById("references-list");e&&"undefined"!=typeof REFERENCES&&(e.innerHTML=REFERENCES.map(e=>`\n        <li>\n            <a href="${e.link}" target="_blank" rel="noopener noreferrer">📚 ${e.text}</a>\n        </li>\n    `).join(""))}function initThemeToggle(){const e=document.getElementById("theme-toggle");e&&e.addEventListener("click",()=>{const n=document.body.classList.toggle("light-theme");localStorage.setItem("theme",n?"light":"dark"),e.textContent=n?"🌙":"☀️"})}document.addEventListener("DOMContentLoaded",()=>{renderStats(),renderZodiacSelector(),selectZodiacSign("aries"),renderTimeline(),renderReferences(),initThemeToggle()}),window.selectZodiacSign=function(e){if("undefined"==typeof ZODIAC_SIGNS)return;document.querySelectorAll(".zodiac-btn").forEach(e=>e.classList.remove("active"));const n=document.getElementById(`btn-zodiac-${e}`);n&&n.classList.add("active");const t=ZODIAC_SIGNS.find(n=>n.id===e);if(!t)return;const i=document.getElementById("detail-name"),o=document.getElementById("detail-month"),d=document.getElementById("detail-symbol"),s=document.getElementById("detail-metal"),r=document.getElementById("detail-mint"),c=document.getElementById("detail-obverse"),l=document.getElementById("detail-reverse"),a=document.getElementById("detail-history");i&&(i.textContent=t.name),o&&(o.innerHTML=`<strong>Solar Month:</strong> ${t.month}`),d&&(d.innerHTML=`<strong>Astrological Symbol:</strong> ${t.symbol}`),s&&(s.innerHTML=`<strong>Coin Metals:</strong> ${t.metal}`),r&&(r.innerHTML=`<strong>Mint & Regnal Year:</strong> ${t.mint}`),c&&(c.innerHTML=`<strong>Obverse Imagery:</strong> ${t.obverseDescription}`),l&&(l.innerHTML=`<strong>Reverse Persian Inscription:</strong> <em>"${t.reverseInscription}"</em>`),a&&(a.innerHTML=`<strong>Historical Context:</strong> ${t.history}`)};